SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");
a:=eval Read("work/deg10/next_cases_20261030/C242/geometry/x0_42_proven_picard.m");k:=GF(5);PP:=PolynomialRing(k);B<s>:=FunctionField(k);RF<Y>:=PolynomialRing(B);function Rat(v)return B!(PP!v[1])/B!(PP!v[2]);end function;p:=RF![Rat(v):v in a[1]];p/:=LeadingCoefficient(p);F<y>:=FunctionField(p);function FF(v)return F![Rat(w):w in v];end function;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);function DP(v)OO:=v[1] eq 1 select OF else OI;return Place(ideal<OO|[FF(x):x in v[3]]>);end function;coords:=[FF(v):v in a[7]];cs:=[DP(v):v in a[11]];z,t:=Explode(coords);keys:=[[Valuation(f,q):f in [z,z+1,9*z+1,t]]:q in cs];assert #Seqset(keys) eq 8;which:=AssociativeArray();for i in [1..8] do which[keys[i]]:=i;end for;
Y0:=MDX1(42,k);C:=Curve(Y0);K0:=FunctionField(C);AF,mp:=AlgorithmicFunctionField(K0);E:=EllipticCurve([mp(K0!v):v in Y0`_E]);Q:=E![mp(K0!v):v in Y0`_P];assert 42*Q eq E!0;bc6:=TateNormalForm_bc(E,7*Q);bc7:=TateNormalForm_bc(E,6*Q);zs:=bc6[2];v7:=bc7[1]/bc7[2];ts:=(v7^3-3*v7+1)/(v7*(v7-1))-8;fs:=[zs,zs+1,9*zs+1,ts];assert bc6[1] eq zs+zs^2;D7:=ts^2+13*ts+49;N7:=ts^2+5*ts+1;assert jInvariant(E) eq N7^3*D7/ts;
scs:=Cusps(Y0);os:=CuspOrbitsQ(Y0);index:=AssociativeArray();finite:=[* *];fibre:=[0:i in [1..8]];
for i in [1..#scs] do q:=scs[i];sp,mm:=Support(FunctionFieldDivisor(Divisor(q)));assert #sp eq 1 and mm[1] eq 1;sig:=[Valuation(f,sp[1]):f in fs];assert IsDefined(which,sig);j:=which[sig];index[q]:=j;fibre[j]+:=Degree(q);Append(~finite,[*i,Degree(q),j,sig*]);end for;assert fibre eq [6:i in [1..8]];
Zn:=FreeAbelianGroup(#a[6][1]);G,qG:=quo<Zn|[Zn!v:v in a[6]]>;cc:=[qG(Zn!v):v in a[10]];H:=sub<G|[qG(Zn!v):v in a[13]]>;hg:=[];global:=[* *];degrees:=[[]:i in [1..8]];
for i in [1..#os] do o:=os[i];sp,mm:=Support(o);ims:={index[q]:q in sp};assert #ims eq 1;j:=Rep(ims);d:=Degree(o);Append(~hg,d*cc[j]);Append(~degrees[j],d);Append(~global,[*i,d,j,[Index(scs,q):q in sp],mm*]);end for;assert sub<G|hg> eq H;
weights:=[GCD(v):v in degrees];assert weights eq [r[3]:r in a[15]];base:=DP(a[12]);ibase:=Index(cs,base);assert weights[ibase] eq 1;
Write("work/deg10/next_cases_20261030/C242/geometry/x0_42_direct_cusp_pushforward.m",Sprint([*keys,finite,global,weights,fibre,Invariants(H),[Eltseq(v):v in hg],true*]):Overwrite:=true);printf"C242_X0_42_DIRECT_GLOBAL_CUSP_PUSHFORWARD_PASS source_cusps=%o global_orbits=%o H=%o weights=%o cpu=%o\n",#scs,#os,Invariants(H),weights,Cputime(tt);quit;
